roms.plate_css:
background: repeating-linear-gradient(
    to bottom,
    blue 0px,
    darkblue 2px,
    blue 3px,
    darkblue 4px
  );
box-shadow: inset 0 0 6px #00000033;
font-size: 0.7rem;
border: 1px solid blue;
box-shadow: 1px 1px 0 #ffffff33, -1px -1px #333;

background-color: #0f172a; /* Slate 900 */
  background-image: 
    radial-gradient(rgba(255, 255, 255, 0.15) 1px, transparent 1px), 
    radial-gradient(rgba(255, 255, 255, 0.15) 1px, transparent 1px);
  background-size: 24px 24px;
  background-position: 0 0, 12px 12px; /* Staggers the dots */

background-color: #1a1018;
font-weight: 700;
background-image: radial-gradient(#2a1520, #0c0a0e 120%);
color: #c44a6a;
border: 1px dashed #c44a6a;

background-color: darkred;
font-weight: 700;
background-image: radial-gradient(darkred, #051c08 120%);
color: red;
border: 1px dashed darkred;

background: linear-gradient(160deg, #2a2218 0%, #16130f 55%, #1a1410 100%);
color: #e0a050;
font-family: IBM Plex Mono, monospace;
font-weight: 600;
border: 1px solid #c46b3a;
box-shadow: inset 0 0 8px #00000044;
